function showBatchTrash(){const ids=selectedPageIds(state.pages,state.selectedPages);if(!ids.length)return;modal(t('trashSelectedPages'),`<p>${t('batchTrashHint')}</p><p><strong>${ids.length} ${t('pageCount')}</strong></p><div class="selection-preview">${ids.slice(0,12).map(id=>`<p>${e(state.pages.find(p=>p.id===id).title)}</p>`).join('')}${ids.length>12?'<p>…</p>':''}</div><div class="modal-footer">${button(t('cancel'),'closeModal')}${button(t('confirmTrashSelected'),'confirmTrashSelected','danger','trash')}</div>`);}
async function performBatchTrash(){const workspaceId=state.config.activeId,ids=selectedPageIds(state.pages,state.selectedPages),revisions=Object.fromEntries(state.pages.map(p=>[p.id,p.revision]));state.busy=true;closeModal();render();try{await flush();for(const p of state.pages)if(ids.includes(p.id))revisions[p.id]=p.revision;const result=await api('trashMany',{workspaceId,ids,deleted:true,revisions});state.selectedPages.clear();await refresh();if(state.page){const current=state.pages.find(p=>p.id===state.page.id&&!p.deleted);if(current)state.page=clone(current);else{state.page=null;state.route='home';}}toast(t('moveTrash')+' '+result.count);}finally{state.busy=false;render();}}
async function showPurge(options){const workspaceId=state.config.activeId;state.busy=true;closeModal();render();let plan;try{await flush();plan=await api('purgePreview',{workspaceId,...options});}finally{state.busy=false;render();}state.purgePlan={workspaceId,preview:plan};modal(t('purgeTitle'),`<p class="form-hint">${t('purgeHint')}</p><div class="purge-preview"><p>${t('purgePages')}<strong>${plan.ids.length}</strong></p><p>${t('purgeAssets')}<strong>${plan.assets.length}</strong></p><p>${t('purgeBytes')}<strong>${byteSize(plan.bytes)}</strong></p></div><p class="form-hint">${t('purgeHistoryHint')}</p><div class="modal-footer">${button(t('cancel'),'closeModal')}${button(t('confirmPurge'),'confirmPurge','danger','trash',!plan.ids.length?'disabled':'')}</div>`);}
async function performPurge(){const plan=state.purgePlan;if(!plan||plan.workspaceId!==state.config.activeId)throw new Error(t('purgeWorkspaceChanged'));state.purgePlan=null;state.busy=true;closeModal();render();try{const result=await api('purgeTrash',{...plan,confirmed:true});await refresh();state.trashSelected.clear();toast(t(result.errors.length?'purgeStopped':'purgeDone')+' '+byteSize(result.bytes)+(result.errors.length?'；'+result.errors.join('；'):''),!!result.errors.length);}finally{state.busy=false;render();}}
let contextOrigin=null;
function closeContextMenu(restore=false){$('#context-root')?.replaceChildren();if(restore&&contextOrigin?.isConnected)contextOrigin.focus();contextOrigin=null;}
function showContextMenu(id,x,y,origin){if(state.busy)return;const page=contextPages().find(p=>p.id===id&&!p.deleted);if(!page)return;closeContextMenu();contextOrigin=origin;$('#context-root').innerHTML=`<div class="page-context-menu" role="menu" aria-label="${t('pageMenu')}"><div class="context-title">${e(page.icon)} ${e(page.title)}</div>${pageMenuItems(page).map(item=>`<button type="button" role="menuitem" data-action="${item.action}" data-id="${id}" class="${item.danger?'danger':''}" ${item.disabled?'disabled':''}>${icon(item.icon,17)}<span>${e(item.label)}</span></button>`).join('')}</div>`;const menu=$('.page-context-menu'),rect=menu.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(x,innerWidth-rect.width-8))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-rect.height-8))+'px';menu.querySelector('button:not([disabled])')?.focus();}
function pageContextTarget(target){const entry=target.closest('.tree-entry,.page-row,.favorite-nav,.page-card,.search-result');const link=entry?.matches('[data-action="page"]')?entry:entry?.querySelector('[data-action="page"][data-id]');return link?.dataset.id?{id:link.dataset.id,origin:link}:null;}
async function contextMutation(id,mutate,trash=false){const workspaceId=state.config.activeId;state.busy=true;closeContextMenu();closeModal();render();try{await flush();const page=clone(state.pages.find(p=>p.id===id&&!p.deleted));if(!page)throw new Error(t('pageNotFound'));if(trash)await api('trash',{workspaceId,id,deleted:true});else{mutate(page);await api('save',{workspaceId,page});}await refresh();if(state.page){const current=state.pages.find(p=>p.id===state.page.id&&!p.deleted);if(current)state.page=clone(current);else{state.page=null;state.route='home';}}toast(t(trash?'moveTrash':'saved'));}finally{state.busy=false;render();}}
async function handlePageMenu(action,id){closeContextMenu();const page=contextPages().find(p=>p.id===id&&!p.deleted);if(!page)throw new Error(t('pageNotFound'));if(action==='pageMenuOpen'){await navigate(id);return;}if(['pageMenuRename','pageMenuMove'].includes(action)&&page.locked){toast(t('readonly'));return;}
 if(action==='pageMenuFavorite'){await contextMutation(id,p=>{p.favorite=!p.favorite;});return;}if(action==='pageMenuDuplicate'){await contextMutation(id,p=>{p.id='';p.revision=0;p.favorite=false;p.title+=' · '+t('copySuffix');});return;}
 if(action==='pageMenuTrash'){modal(t('moveTrash'),`<p><strong>${e(page.title)}</strong></p><p class="form-hint">${t('deleteWarning')}</p><div class="modal-footer">${button(t('cancel'),'closeModal')}${button(t('moveTrash'),'pageMenuConfirmTrash','danger','trash',`data-id="${id}"`)}</div>`);return;}if(action==='pageMenuConfirmTrash'){await contextMutation(id,()=>{},true);return;}
 const rename=action==='pageMenuRename';modal(t(rename?'renamePage':'movePage'),`<form id="page-context-form"><p class="form-hint">${e(page.title)}</p>${rename?`<label class="form-field">${t('titleHint')}<input name="title" required value="${e(page.title)}"></label>`:`<label class="form-field">${t('parent')}<select name="parentId"><option value="">${t('root')}</option>${state.pages.filter(p=>!p.deleted&&!descendants(state.pages,id).has(p.id)).map(p=>`<option value="${p.id}" ${p.id===page.parentId?'selected':''}>${e(p.icon+' '+p.title)}</option>`).join('')}</select></label>`}<div class="modal-footer"><button type="submit" class="button primary">${t('save')}</button></div></form>`);
 const form=$('#page-context-form');if(rename){form.elements.title.focus();form.elements.title.select();}form.onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form));if(rename&&!data.title.trim()){toast(t('pageNameRequired'),true);return;}try{await contextMutation(id,p=>{if(rename)p.title=data.title.trim();else p.parentId=data.parentId;});}catch(error){toast(error.message,true);}};
}
document.addEventListener('contextmenu',event=>{const target=pageContextTarget(event.target);if(target&&!state.busy){event.preventDefault();showContextMenu(target.id,event.clientX,event.clientY,target.origin);}});
document.addEventListener('pointerdown',event=>{if(!event.target.closest('.page-context-menu'))closeContextMenu();});
document.addEventListener('scroll',()=>closeContextMenu(),true);window.addEventListener('resize',()=>closeContextMenu());
document.addEventListener('keydown',event=>{const menu=$('.page-context-menu');if(menu){const items=[...menu.querySelectorAll('button:not([disabled])')],i=items.indexOf(document.activeElement);if(event.key==='Escape'){event.preventDefault();closeContextMenu(true);return;}if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();items[event.key==='Home'?0:event.key==='End'?items.length-1:(i+(event.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();}if(event.key==='Tab')closeContextMenu();}else if(event.shiftKey&&event.key==='F10'){const target=pageContextTarget(document.activeElement);if(target){event.preventDefault();const rect=target.origin.getBoundingClientRect();showContextMenu(target.id,rect.left,rect.bottom,target.origin);}}});
async function showImportRepair(){
 const workspaceId=state.config.activeId;state.busy=true;closeModal();render();try{await flush();await refresh();if(state.page)state.page=clone(state.pages.find(p=>p.id===state.page.id));}finally{state.busy=false;render();}const suggestions=importRepairSuggestions(state.pages,state.page?.database?state.page.id:'');
 modal(t('repairImport'),`<p class="form-hint">${t('repairHint')}</p><form id="repair-form"><h3>${t('repairFields')}</h3>${suggestions.fields.map(f=>`<label class="repair-item"><input type="checkbox" name="fields" value="${f.pageId}" checked><span><strong>${e(f.page.title)}</strong><small>${f.changes.map(c=>e(c.name)+' → '+t(c.type==='status'?'statusProperty':c.type==='number'?'numberProperty':c.type)).join('、')}</small></span></label>`).join('')}<h3>${t('repairParents')}</h3>${suggestions.parents.map(p=>`<label class="repair-item"><input type="checkbox" name="parents" value="${p.pageId}" checked><span>${e(p.title)} → ${e(p.parentTitle)}</span></label>`).join('')}${!suggestions.fields.length&&!suggestions.parents.length?`<p class="form-hint">${t('repairNone')}</p>`:''}<div class="modal-footer"><button type="submit" class="button primary" ${!suggestions.fields.length&&!suggestions.parents.length?'disabled':''}>${t('applyRepair')}</button></div></form>`,true);
 $('#repair-form').onsubmit=async event=>{event.preventDefault();const selection=new FormData(event.target),changes=new Map();for(const f of suggestions.fields)if(selection.getAll('fields').includes(f.pageId))changes.set(f.pageId,clone(f.page));for(const p of suggestions.parents)if(selection.getAll('parents').includes(p.pageId)){const page=changes.get(p.pageId)||clone(state.pages.find(page=>page.id===p.pageId));page.parentId=p.parentId;changes.set(p.pageId,page);}if(!changes.size)return;
  let saved=0;state.busy=true;closeModal();render();try{await api('commit',{workspaceId});for(const page of changes.values()){await api('save',{workspaceId,page});saved++;}toast(t('repairDone')+' '+saved);}catch(error){toast(t('repairFailed')+saved+'；'+error.message,true);}finally{try{await refresh();if(state.page)state.page=clone(state.pages.find(p=>p.id===state.page.id));}catch(error){toast(error.message,true);}finally{state.busy=false;render();}}
 };
}
